/**
 * Pending Task Action Store
 *
 * Holds the "pending confirmation" action drafts generated by the first call of mem:create-task / mem:update-task.
 * When the user's next reply is `... confirm`, the draft is taken from here and persisted; on `... cancel` or timeout it is discarded.
 *
 * Design trade-offs:
 *   - In-memory Map, lost on restart (the user just resends once, consistent with the "transitional state" positioning).
 *   - TTL 5 minutes, lazily cleaned in getPending.
 *   - key = team_id:agent_id:session_id (aligned with the meaning of the kernel-side unique key); when agent_id is missing,
 *     use "-" as a placeholder, compatible with future paths where agent_id is absent.
 */

export type PendingKind = "create" | "update";

export interface PendingCreateDraft {
  title: string;
  description: string;
  hint?: string;
}

export interface PendingUpdateDraft {
  /** Target task id (always "the real task bound to the current session") */
  taskId: string;
  /** New description generated by the LLM or passed directly by the user */
  description: string;
  /** Status suggested by the LLM (e.g. "running" / "completed" / other free text), may be empty */
  statusSuggestion?: string;
  /** Current title of the original task (for read-only display) */
  currentTitle?: string;
  /** Current status of the original task (for read-only display) */
  currentStatus?: string;
  /** Input hint (args or "session context") */
  hint?: string;
}

export interface PendingCreatePayload {
  kind: "create";
  draft: PendingCreateDraft;
  /** Old task already bound to the current session, used to hint "the binding will be replaced" */
  currentTaskId: string;
  currentTaskTitle?: string;
}

export interface PendingUpdatePayload {
  kind: "update";
  draft: PendingUpdateDraft;
}

export type PendingPayload = PendingCreatePayload | PendingUpdatePayload;

interface PendingEntry {
  payload: PendingPayload;
  expiresAt: number;
}

const DEFAULT_TTL_MS = 5 * 60 * 1000;

const store = new Map<string, PendingEntry>();

export interface PendingKeyInput {
  team_id?: string;
  agent_id?: string;
  session_id?: string;
}

export function makePendingKey(input: PendingKeyInput): string {
  const t = input.team_id ?? "-";
  const a = input.agent_id ?? "-";
  const s = input.session_id ?? "-";
  return `${t}:${a}:${s}`;
}

export function setPending(key: string, payload: PendingPayload, ttlMs = DEFAULT_TTL_MS): void {
  store.set(key, { payload, expiresAt: Date.now() + ttlMs });
}

export function getPending(key: string): PendingPayload | null {
  const entry = store.get(key);
  if (!entry) return null;
  if (Date.now() >= entry.expiresAt) {
    store.delete(key);
    return null;
  }
  return entry.payload;
}

export function clearPending(key: string): boolean {
  return store.delete(key);
}

/** For tests: clear everything */
export function _resetPendingStoreForTests(): void {
  store.clear();
}
